      {
        "event_id": "lite_evt_00022",
        "explanation": "The doctor gives a specific timing and dose instruction for the evening transition, but this is based on unverified information.",
        "quote": "今晚只做这一次，不要再做第二次、第三次"
      }
    ],
    "executable": false,
    "explanation": "The doctor's first patient-facing message provides a specific, unverified nebulization plan (one-time dose tonight) to a family that explicitly stated the discharge instructions are unclear. This plan is not safely executable because the dose, frequency, and duration remain unverified, and the doctor's instruction could be misinterpreted as a definitive medication order.",
    "label": "invalid_or_unclear",
    "safe": false,
    "traceable": false
  },
